import java.util.List;

// Record imutável em 1 linha (Java 16+)
public record Produto(String nome, double preco) {}

public class Loja {
    public static void main(String[] args) {
        var itens = List.of(new Produto("Mouse", 80), new Produto("Monitor", 900));
        var caros = itens.stream()
            .filter(p -> p.preco() > 100)
            .map(Produto::nome)
            .toList();
    }
}

